<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesUidVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesVersionVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesListRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesItem;
use PHPUnit\Framework\TestCase;

class UserRoleAssignamentRolesListRefUnitTest extends TestCase
{
    public function test_iterator(): void
    {
        $one = new UserRoleAssignamentRolesItem(
            uid: UserRoleAssignamentRolesUidVO::from('one'),
            role: UserRoleAssignamentRolesRoleVO::from(new RoleRef('one')),
            version: UserRoleAssignamentRolesVersionVO::from(1)
        );
        $two = new UserRoleAssignamentRolesItem(
            uid: UserRoleAssignamentRolesUidVO::from('one'),
            role: UserRoleAssignamentRolesRoleVO::from(new RoleRef('one')),
            version: UserRoleAssignamentRolesVersionVO::from(1)
        );
        $list = UserRoleAssignamentRolesListRef::fromArray([$one, $two]);
        foreach ($list as $_K => $item) {
            $this->assertEquals('one', $item->uid());
        }
    }
    public function test_invalid_builder(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $list = UserRoleAssignamentRolesListRef::fromArray(['none']);
    }
}
